'use strict';

/**
* Return the index of the first element in a sorted single-precision floating-point strided array which is greater than or equal to a specified search element.
*
* @module @stdlib/blas/ext/base/sindex-of-greater-than-equal-sorted
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var sindexOfGreaterThanEqualSorted = require( '@stdlib/blas/ext/base/sindex-of-greater-than-equal-sorted' );
*
* var x = new Float32Array( [ 1.0, 2.0, 2.0, 3.0 ] );
*
* var idx = sindexOfGreaterThanEqualSorted( x.length, 2.0, x, 1 );
* // returns 1
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var sindexOfGreaterThanEqualSorted = require( '@stdlib/blas/ext/base/sindex-of-greater-than-equal-sorted' );
*
* var x = new Float32Array( [ 1.0, 2.0, 2.0, 3.0 ] );
*
* var idx = sindexOfGreaterThanEqualSorted.ndarray( x.length, 2.0, x, 1, 0 );
* // returns 1
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var sindexOfGreaterThanEqualSorted;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	sindexOfGreaterThanEqualSorted = main;
} else {
	sindexOfGreaterThanEqualSorted = tmp;
}


// EXPORTS //

module.exports = sindexOfGreaterThanEqualSorted;

// exports: { "ndarray": "sindexOfGreaterThanEqualSorted.ndarray" }
